import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"Stage 0 · Definition & Prototype","description":"Hearth Stage 0 development module: product wedge, real-task baseline, clickable prototype, contracts, evaluation, and engineering baseline.","frontmatter":{"title":"Stage 0 · Definition & Prototype","description":"Hearth Stage 0 development module: product wedge, real-task baseline, clickable prototype, contracts, evaluation, and engineering baseline.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-0.md","filePath":"en/delivery/stage-0.md","lastUpdated":null}'),r={name:"en/delivery/stage-0.md"};function o(s,e,l,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<p class="eyebrow">MODULE 0 / 7</p><h1 id="stage-0-·-definition-prototype" tabindex="-1">Stage 0 · Definition &amp; Prototype <a class="header-anchor" href="#stage-0-·-definition-prototype" aria-label="Permalink to &quot;Stage 0 · Definition &amp; Prototype&quot;">​</a></h1><p class="lead">Lock down who the product is for, what the first verifiable task is, and how success will be judged before building the execution kernel. Stage 0 must produce enough evidence to support the first runnable vertical slice.</p><h2 id="questions-this-module-answers" tabindex="-1">Questions This Module Answers <a class="header-anchor" href="#questions-this-module-answers" aria-label="Permalink to &quot;Questions This Module Answers&quot;">​</a></h2><ul><li>Who is the first real user, and what is the first high-frequency, verifiable task wedge?</li><li>Why use Hearth instead of Codex, a chat assistant, or a collection of automation scripts?</li><li>What does the user see when a task is created, running, awaiting approval, failed, or recoverable?</li><li>Which stable contracts do the UI, backend, executors, approvals, and evaluation depend on?</li></ul><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><ul><li>An empty repository and one first user willing to provide real tasks and feedback.</li><li>Ability to record both a fully manual baseline and a direct-Codex baseline.</li><li>No real high-risk external side effects yet.</li></ul><h2 id="development-steps" tabindex="-1">Development Steps <a class="header-anchor" href="#development-steps" aria-label="Permalink to &quot;Development Steps&quot;">​</a></h2><ol><li><strong>Lock the product wedge.</strong> Choose the first user, first task family, and explicit non-goals; write the positioning and a &quot;what we do not do&quot; list.</li><li><strong>Build a real task set.</strong> Collect 20–30 real tasks and select at least 12 with clear inputs, artifacts, and acceptance methods, including success, failure, approval, and takeover cases.</li><li><strong>Run baselines.</strong> Record manual minutes, success rate, Tokens, failure types, and user friction for both manual work and direct Codex use.</li><li><strong>Create an end-to-end prototype.</strong> Cover Today, Needs You, Artifacts, and Settings, plus queued, running, awaiting approval, needing information, completed, failed, and recoverable states.</li><li><strong>Define core contracts.</strong> Fix fields and state transitions for Task, Ticket, Run, Event, Executor, Approval, Artifact, Receipt, and Budget; define Task Pack, Result, failure classes, and UI projections.</li><li><strong>Set up the engineering skeleton.</strong> Initialize the monorepo, type checks, lint, tests, CI, ADR template, documentation structure, and a fake executor.</li><li><strong>Establish evaluation and security baselines.</strong> Build a runner, scoring, and human review for the 12 tasks; complete the threat model, risk tiers, approval matrix, and secret-handling rules.</li><li><strong>Rehearse the contracts.</strong> Drive the full prototype with a mock server and verify that the same event stream reconstructs UI state without pretending unknown states are successful.</li></ol><h2 id="increment-breakdown" tabindex="-1">Increment Breakdown <a class="header-anchor" href="#increment-breakdown" aria-label="Permalink to &quot;Increment Breakdown&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Increment</th><th>User-visible outcome</th><th>Completion evidence</th></tr></thead><tbody><tr><td>D0.1 Product wedge and task baseline</td><td>A clear explanation of why the first user needs Hearth</td><td>12+ real tasks, two baselines, non-goals, and success metrics</td></tr><tr><td>D0.2 End-to-end prototype</td><td>A new user can create, approve, retrieve artifacts, and recover without instructions</td><td>Desktop/mobile prototype, all states, usability review</td></tr><tr><td>D0.3 Protocol and data contracts</td><td>Every prototype state maps to stable fields and events</td><td>Entity definitions, state machine, projection contracts, contract tests</td></tr><tr><td>D0.4 Evaluation, security, and engineering baseline</td><td>Every later increment can be verified from day one</td><td>Evaluation runner, threat model, approval matrix, CI, fake executor</td></tr></tbody></table><h2 id="exit-checklist" tabindex="-1">Exit Checklist <a class="header-anchor" href="#exit-checklist" aria-label="Permalink to &quot;Exit Checklist&quot;">​</a></h2><ul><li>[ ] At least 12 tasks have inputs, artifacts, acceptance criteria, and failure samples.</li><li>[ ] A new user can complete the main path in the prototype; each state has one primary action.</li><li>[ ] Pages do not depend on internal database fields; the event stream reconstructs UI projections.</li><li>[ ] High-risk actions have an approval path; evaluation is repeatable; CI catches contract and schema regressions.</li><li>[ ] The fake executor drives the complete UI flow with no real external side effects.</li></ul><h2 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h2><ul><li>Do not build the whole kernel before the UI.</li><li>Do not connect real sending, payments, deletion, or system-setting changes.</li><li>Do not treat &quot;the documents are written&quot; as a substitute for a clickable prototype and repeatable evaluation.</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p>Continue to <a href="/hearth-os/en/delivery/stage-1.html">Stage 1 · Durable Kernel &amp; MVP</a>: deliver the walking skeleton first, then close MVP-1.</p>',17)])])}const f=t(r,[["render",o]]);export{p as __pageData,f as default};
